        id: "intro",
        type: "paragraph",
        content: "The **Ujjain to Omkareshwar distance** journey is one of the most popular additions to a Madhya Pradesh pilgrimage itinerary. Omkareshwar, located where the Narmada river forms the shape of the sacred Om symbol, is home to Omkareshwar Jyotirlinga, making it a natural pairing with Mahakaleshwar in Ujjain. Combining both shrines in a single trip is what pilgrims call the **Mahakaleshwar Omkareshwar yatra**, covering two of India's twelve Jyotirlingas in one journey. For travel tips to reach Ujjain first, read our [How to Reach Ujjain guide](/blog/how-to-reach-ujjain-best-time-visit-mahakaleshwar)."
