        extraContent: "The standard **Chintaman Ganesh mandir auto fare** from Mahakal Temple is ₹200 to ₹300 for a private one-way drop. A round-trip auto including waiting time costs around ₹450 to ₹600. Electric rickshaws and app-based cabs also operate along this well-paved route. For pilgrims keeping track of **Chintaman Ganesh temple distance from station**, the ride takes approximately 20 to 25 minutes under ordinary traffic conditions. General darshan is free of cost."
