        extraContent: "During peak periods like Shravan Maas, Navratri, or major festival weekends, rates can rise to ₹1,000 to ₹1,200. Comparing **e rickshaw vs auto rickshaw full day hire Ujjain**: battery e-rickshaws are slower and have slightly firmer seating, but they offer smooth silent rides for ₹600 to ₹800. Regular petrol or CNG autos handle outer highway stretches (like Chintaman Ganesh or Triveni) much faster."
