        extraContent: "Understanding **Bade Ganesh mandir ki murti ki visheshta** reveals an extraordinary sculptural technique. The colossal seated Ganesha was not carved from a single quarry block. Instead, it was sculpted using holy soil and sanctified water brought from seven sacred pilgrim tirthas (Sapta Sarita), mixed with crushed gemstones, coral, pearl powder, jaggery, fenugreek, and traditional herbs. Coated in radiant bright sindoor (vermilion), the benign, colossal face radiates supreme peace and wisdom."
