        extraContent: "The temple is also home to a rare shrine of Panchmukhi (five-faced) Hanuman, revered for protecting devotees against evil spirits and severe planetary afflictions. Pandit Narayan Vyas also established the **Jyotish vidya learning centre Bade Ganesh Ujjain**, where young scholars continue to study Sanskrit grammar, astronomical Panchang calculation, and predictive horoscope interpretation in traditional gurukul style."
