        h2: "Kaliadeh Palace Water Channels and Ancient Sun Shrines",
        content: "Located approximately 8 km north of the city on an island in the Shipra, Kaliadeh Palace is one of the most intriguing historical sites in central India. Built by the Sultans of Mandu in the 15th century over the foundations of an ancient Surya (Sun) Temple, the complex features Persian-style waterways.",
        extraContent: "The **Kaliadeh palace water channels and architecture** utilized intricate masonry ducts and 52 cooling water pools (kunds) to divert river water across shaded stone pavilions during scorching summer months. Although sections of the palace are weathered ruins, the nearby ancient Sun Temple remains active. Inquiring about **distance of Kaliadeh palace from Mahakal mandir**, the 20-minute auto drive passes lush agricultural countryside, offering a rare glimpse of quiet historic Malwa."
